    "kernel_code": "1: \"\"\"Forward cyclic NTT with fused butterfly stages.\n2: \n3: Original synthetic Triton implementation, not an upstream cryptographic kernel.\n4: \"\"\"\n5: import torch\n6: import triton\n7: import triton.language as tl\n8: \n9: _Q = 3329\n10: _ROOT = 17\n11: _R = 1 << 16\n12: _R_INV = pow(_R, -1, _Q)\n13: \n14: \n15: def _coefficient_product(left, right):\n16:     return (left * right) % _Q\n17: \n18: \n19: def _make_coefficients(width):\n20:     \"\"\"Pack the coefficient banks for each fused stage and optional last stage.\"\"\"\n21:     omega = pow(_ROOT, 256 // width, _Q)\n22:     result = []\n23:     half = 1\n24:     for _ in range((width.bit_length() - 1) // 2):\n25:         first = [(_R * pow(omega, j * width // (2 * half), _Q)) % _Q\n26:                  for j in range(half)]\n27:         second = [(_R * pow(omega, j * width // (4 * half), _Q)) % _Q\n28:                   for j in range(half)]\n29:         upper = [(_R * pow(omega, (j + half) * width // (4 * half), _Q)) % _Q\n30:                  for j in range(half)]\n31:         cross_low = [_coefficient_product(a, b) for a, b in zip(first, second)]\n32:         cross_high = [_coefficient_product(a, b) for a, b in zip(first, upper)]\n33:         result.extend(first + second + upper + cross_low + cross_high)\n34:         half *= 4\n35:     if (width.bit_length() - 1) % 2:\n36:         result.extend([(_R * pow(omega, j, _Q)) % _Q for j in range(width // 2)])\n37:     return result\n38: \n39: \n40: @triton.jit\n41: def _multiply(value, coefficient):\n42:     product = value.to(tl.int64) * coefficient.to(tl.int64)\n43:     correction = (product * 3327) & 65535\n44:     reduced = (product + correction * 3329) >> 16\n45:     return tl.where(reduced >= 3329, reduced - 3329, reduced).to(tl.int32)\n46: \n47: \n48: @triton.jit\n49: def _transform_kernel(X, COEFFICIENTS, OUT, N: tl.constexpr, LOG_N: tl.constexpr):\n50:     row = tl.program_id(0)\n51:     lane = tl.arange(0, N)\n52:     source = tl.full((N,), 0, tl.int32)\n53:     for bit in tl.static_range(0, LOG_N):\n54:         source = source | (((lane >> bit) & 1) << (LOG_N - 1 - bit))\n55:     value = tl.load(X + row * N + source).to(tl.int32)\n56: \n57:     for stage in tl.static_range(0, LOG_N // 2):\n58:         half = 1 << (2 * stage)\n59:         local = lane % half\n60:         base = (lane // (4 * half)) * (4 * half) + local\n61:         quadrant = (lane // half) & 3\n62:         a = tl.gather(value, base, axis=0)\n63:         b = tl.gather(value, base + half, axis=0)\n64:         c = tl.gather(value, base + 2 * half, axis=0)\n65:         d = tl.gather(value, base + 3 * half, axis=0)\n66:         start = 5 * (half - 1) // 3\n67:         first = tl.load(COEFFICIENTS + start + local)\n68:         second = tl.load(COEFFICIENTS + start + half + local)\n69:         upper = tl.load(COEFFICIENTS + start + 2 * half + local)\n70:         cross_low = tl.load(COEFFICIENTS + start + 3 * half + local)\n71:         cross_high = tl.load(COEFFICIENTS + start + 4 * half + local)\n72:         p = _multiply(b, first)\n73:         c_low = _multiply(c, second)\n74:         c_high = _multiply(c, upper)\n75:         d_low = _multiply(d, cross_low)\n76:         d_high = _multiply(d, cross_high)\n77:         lower_sum = a + p + c_low + d_low\n78:         lower_difference = a + p - c_low - d_low\n79:         upper_sum = a - p + c_high - d_high\n80:         upper_difference = a - p - c_high + d_high\n81:         value = tl.where(quadrant == 0, lower_sum,\n82:                          tl.where(quadrant == 1, upper_sum,\n83:                                   tl.where(quadrant == 2, lower_difference, upper_difference)))\n84:         value = (value + 2 * 3329) % 3329\n85: \n86:     if LOG_N % 2:\n87:         half = N // 2\n88:         local = lane % half\n89:         left = tl.gather(value, local, axis=0)\n90:         right = tl.gather(value, local + half, axis=0)\n91:         start = 5 * ((1 << (2 * (LOG_N // 2))) - 1) // 3\n92:         coefficient = tl.load(COEFFICIENTS + start + local)\n93:         weighted = _multiply(right, coefficient)\n94:         value = tl.where(lane < half, left + weighted, left - weighted)\n95:         value = (value + 3329) % 3329\n96:     tl.store(OUT + row * N + lane, value)\n97: \n98: \n99: def validate_inputs(x, require_cuda=True):\n100:     \"\"\"Validate the complete public field and tensor domain.\"\"\"\n101:     def require(condition, message):\n102:         if not condition:\n103:             raise ValueError(message)\n104: \n105:     require(not torch.is_inference_mode_enabled(), \"ordinary execution mode required\")\n106:     require(type(x) is torch.Tensor, \"ordinary torch.Tensor required\")\n107:     require(x.layout == torch.strided and x.is_contiguous(), \"contiguous strided input required\")\n108:     require(not x.requires_grad and not x.is_inference(), \"ordinary non-gradient input required\")\n109:     require(not x.is_neg() and not x.is_conj(), \"logical view flags are outside this domain\")\n110:     require(not require_cuda or x.is_cuda, \"CUDA input required by run\")\n111:     require(x.ndim == 2 and 1 <= x.shape[0] <= 128 and x.shape[1] in (64, 128),\n112:             \"x must have shape [B,N], B in [1,128] and N in {64,128}\")\n113:     require(x.dtype == torch.int32, \"int32 input required\")\n114:     require(bool(((x >= 0) & (x < 3329)).all()), \"canonical field values 0..3328 required\")\n115:     return {\"valid\": True, \"batch\": x.shape[0], \"width\": x.shape[1]}\n116: \n117: \n118: def run(x):\n119:     validate_inputs(x)\n120:     batch, width = x.shape\n121:     with torch.cuda.device(x.device):\n122:         coefficients = torch.tensor(_make_coefficients(width), dtype=torch.int32, device=x.device)\n123:         output = torch.empty_like(x)\n124:         _transform_kernel[(batch,)](\n125:             x, coefficients, output, N=width, LOG_N=width.bit_length() - 1, num_warps=4)\n126:     return output\n127: \n128: \n129: def reference(x):\n130:     \"\"\"Direct modular DFT, independent of the coefficient banks and butterflies.\"\"\"\n131:     validate_inputs(x, require_cuda=False)\n132:     width = x.shape[1]\n133:     matrix = [[pow(17, (256 // width) * k * j, 3329) for j in range(width)]\n134:               for k in range(width)]\n135:     coefficients = torch.tensor(matrix, dtype=torch.int64, device=x.device)\n136:     products = x.to(torch.int64)[:, None, :] * coefficients[None, :, :]\n137:     return (products.sum(dim=2) % 3329).to(torch.int32)\n138: \n139: \n140: def make_inputs(device=\"cuda\", batch=7, width=64, seed=0):\n141:     \"\"\"Examples only; every canonical field-valued row is legal.\"\"\"\n142:     generator = torch.Generator(device=\"cpu\").manual_seed(seed)\n143:     x = torch.randint(0, 3329, (batch, width), generator=generator, dtype=torch.int32)\n144:     return (x.to(device),)",
